import java.util.Iterator;
import java.util.List;
import java.util.Random;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * Abstract class for a prey in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Prey extends Animal implements Consumable {

    private static final double DEFAULT_ACTIVENESS = 1.0;
    private static final int SATIATION_THRESHOLD = 10;

    private int foodValue;
    private double activeness;

    // shared random generator to generate consistent results
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for a Prey in the simulation.
     *
     * @param traits    Species-level configuration for this prey.
     * @param foodValue The initial food value carried by this prey.
     * @param randomAge Whether we assign this prey a random age or not.
     * @param field     The field in which this prey resides.
     * @param location  The location in which this prey is spawned into.
     */
    public Prey(AnimalTraits traits, int foodValue, boolean randomAge, Field field, Location location) {
        super(traits, randomAge, field, location);
        this.foodValue  = foodValue;
        this.activeness = DEFAULT_ACTIVENESS;
    }

    /**
     * Returns the activeness multiplier applied during this prey's rest period.
     * Override in each concrete species with the species-specific fraction.
     *
     * @return A double in (0, 1] representing reduced activity.
     */
    abstract protected double getRestActiveness();

    /**
     * Performs one simulation step: ages, breeds, spreads disease, forages, and moves.
     * Dead prey linger on the field so scavengers can eat their corpses.
     */
    @Override
    public void act(List<Entity> newOrganisms, Weather weather, TimeOfDay time) {
        incrementAge();
        setActiveness(DEFAULT_ACTIVENESS);

        if (isAlive()) {
            giveBirth(newOrganisms);

            if (rand.nextDouble() <= getDeathByDiseaseProbability()) {
                remove();
                return;
            }

            if (time == getRestTime()) {
                setActiveness(getRestActiveness());
            }

            if (rand.nextDouble() <= getActiveness()) {
                Location newLocation = rand.nextDouble() <= getDiseaseSpreadProbability()
                    ? findAnimalToInfect() : findFood();

                if (newLocation == null || getFoodValue() > SATIATION_THRESHOLD) {
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }

                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    remove();
                }
            }
        } else {
            decayifDead();
        }
    }

    /**
     * Searches adjacent cells for a living plant to eat.
     *
     * @return The location of the eaten plant, or null if none found.
     */
    @Override
    public Location findFood() {
        Field field = getField();
        Iterator<Location> it = field.adjacentLocations(getLocation()).iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Plant) {
                Plant plant = (Plant) organism;
                if (plant.isAlive()) {
                    plant.setDead();
                    return eat(plant) ? where : null;
                }
            }
        }
        return null;
    }

    /** Clears this prey from the field when it has been eaten. */
    @Override
    public void setEaten() {
        if (getLocation() != null) {
            getField().clear(getLocation());
            setLocationToNull();
            setField(null);
        }
    }

    @Override
    public int getFoodValue() { return foodValue; }

    protected void incrementFoodValue(int amount) { foodValue += amount; }

    /**
     * Eats a plant; infects this prey if the plant is poisonous.
     *
     * @param consumable The plant to be eaten.
     * @return true always (prey always eat what they find).
     */
    @Override
    public boolean eat(Consumable consumable) {
        if (consumable.isPoisonous() && !isInfected()) {
            infect(this);
        }
        incrementFoodValue(consumable.getFoodValue());
        consumable.setEaten();
        return true;
    }

    /** Prey are never poisonous. */
    @Override
    public boolean isPoisonous() { return false; }

    public double getActiveness()               { return activeness; }
    public void   setActiveness(double value)   { activeness = value; }
}

import java.util.List;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * An abstract plant organism present in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Plant extends Organism implements Growable, Consumable {

    private final PlantTraits traits;
    private double size;
    private final int foodValue;
    private final boolean poisonous;
    private double growthRate;
    private double breedingProbability;

    /**
     * Constructor for a plant in the simulation.
     *
     * @param traits    Species-level configuration for this plant.
     * @param poisonous Whether the plant is poisonous or not.
     * @param foodValue The food value of this plant when eaten.
     * @param size      The initial size of this plant.
     * @param randomAge Whether the plant should have a random age or not.
     * @param field     The field in which the plant resides.
     * @param location  The location in which the plant spawns into.
     */
    public Plant(PlantTraits traits, boolean poisonous, int foodValue, double size,
                 boolean randomAge, Field field, Location location) {
        super(randomAge, field, location);
        this.traits    = traits;
        this.size      = size;
        this.foodValue = foodValue;
        this.poisonous = poisonous;
        this.growthRate         = traits.growthRate;
        this.breedingProbability = traits.lowBreedingProbability;
    }

    // ── Organism stat getters (satisfied here so subclasses need not override) ──

    @Override public int    getMaxAge()        { return traits.maxAge; }
    @Override public int    getBreedingAge()   { return traits.breedingAge; }
    @Override public int    getMaxLitterSize() { return traits.maxLitterSize; }

    @Override
    public double getBreedingProbability() { return breedingProbability; }

    // ── Growable interface ─────────────────────────────────────────────────────

    @Override public double getMaxSize()                   { return traits.maxSize; }
    @Override public double getSize()                      { return size; }
    @Override public double getGrowthRate()                { return growthRate; }
    @Override public void   setGrowthRate(double rate)     { growthRate = rate; }

    @Override
    public void grow() {
        size = size * growthRate > traits.maxSize ? 1 : size * growthRate;
        if (size == 0) remove();
    }

    // ── Consumable interface ───────────────────────────────────────────────────

    @Override public int     getFoodValue()  { return foodValue; }
    @Override public boolean isPoisonous()   { return poisonous; }

    @Override
    public void setEaten() {
        if (getLocation() != null) {
            getField().clear(getLocation());
            setLocationToNull();
            setField(null);
        }
    }

    // ── Breeding ───────────────────────────────────────────────────────────────

    @Override
    protected boolean canBreed() {
        return getAge() >= getBreedingAge();
    }

    // ── act() — shared across all plant species ────────────────────────────────

    /**
     * Returns the weather types that boost this plant's breeding probability.
     * Concrete plant classes declare which WeatherTypes trigger the high rate.
     *
     * @return Array of WeatherType values that trigger high breeding probability.
     */
    abstract protected WeatherType[] getBoostWeatherTypes();

    /**
     * Grows and attempts to spread seeds each step, with a boosted breeding
     * probability whenever any of the boost weather types appear in recent history.
     */
    @Override
    public void act(List<Entity> newPlants, Weather weather, TimeOfDay time) {
        if (isAlive()) {
            breedingProbability = traits.lowBreedingProbability;
            for (WeatherType boostType : getBoostWeatherTypes()) {
                if (weather.getRecentWeather().contains(boostType)) {
                    breedingProbability = traits.highBreedingProbability;
                    break;
                }
            }
            grow();
            giveBirth(newPlants);
        }
    }

    /** Allows subclasses to update the breeding probability (kept for compatibility). */
    protected void setBreedingProbability(double probability) {
        this.breedingProbability = probability;
    }
}

